/// A runtime block state id: an index into `STATES`, valid for this build's registry.
pub type StateId = u16;

/// Air is always state 0 (the generator checks it).
pub const AIR: StateId = 0;
/// The brightest flood-light level (sky and block light are 0–15; docs/DAY_NIGHT.md §11).
pub const LIGHT_MAX: u8 = 15;

/// The state named by `name`: a canonical string (`dwell:ladder[facing=east,flooded=false]`), or
/// any form [`parse_state`] takes (properties in any order, missing ones at their defaults; a block
/// id alone is its default state). The build's states first, then registered ones.
pub fn state(name: &str) -> Option<StateId> {
    if let Some(i) = STATES.iter().position(|s| s.name == name) {
        return StateId::try_from(i).ok();
    }
    parse_state(name).ok()
}

/// The full state of liquid state `m` (fill 1, `fillProperty`'s default): one liquid at any
/// fill is the same water. Any other state is its own.
pub fn liquid_full(m: StateId) -> StateId {
    static FULL: std::sync::LazyLock<Vec<StateId>> = std::sync::LazyLock::new(|| {
        (0..STATES.len())
            .map(|m| {
                let s = &STATES[m];
                if !s.liquid || s.fill >= 1.0 {
                    return m as StateId;
                }
                STATES
                    .iter()
                    .position(|x| x.block == s.block && x.fill >= 1.0)
                    .map_or(m as StateId, |i| i as StateId)
            })
            .collect()
    });
    FULL.get(usize::from(m)).copied().unwrap_or(m)
}

/// Liquid `m`'s state nearest fill `frac` (0..1; at least its least fill): how a cell part full
/// of it is written (docs/WATER_FLOW.md §15). A liquid without a fill is always full.
pub fn liquid_at_fill(m: StateId, frac: f64) -> StateId {
    static FILLS: std::sync::LazyLock<std::collections::HashMap<StateId, Vec<(f32, StateId)>>> =
        std::sync::LazyLock::new(|| {
            let mut out: std::collections::HashMap<StateId, Vec<(f32, StateId)>> =
                std::collections::HashMap::new();
            for (i, s) in STATES.iter().enumerate() {
                if s.liquid {
                    out.entry(liquid_full(i as StateId))
                        .or_default()
                        .push((s.fill, i as StateId));
                }
            }
            for v in out.values_mut() {
                v.sort_by(|a, b| a.0.total_cmp(&b.0));
            }
            out
        });
    let full = liquid_full(m);
    let Some(v) = FILLS.get(&full) else {
        return m;
    };
    v.iter()
        .min_by(|a, b| {
            (f64::from(a.0) - frac)
                .abs()
                .total_cmp(&(f64::from(b.0) - frac).abs())
        })
        .map_or(full, |&(_, s)| s)
}

/// The build's own state with this exact canonical string (never a registered one).
pub fn build_state(name: &str) -> Option<StateId> {
    STATES
        .iter()
        .position(|s| s.name == name)
        .and_then(|i| StateId::try_from(i).ok())
}

/// Like [`state`], for names that must exist (built-in content); panics with the name otherwise.
pub fn require(name: &str) -> StateId {
    state(name).unwrap_or_else(|| panic!("unknown block state `{name}`"))
}

/// The fluid named `name` (`dwell:water`).
pub fn fluid(name: &str) -> Option<FluidId> {
    FLUIDS
        .iter()
        .position(|f| f.name == name)
        .and_then(|i| FluidId::try_from(i).ok())
}

/// Like [`fluid`], for names that must exist (built-in content): its table row.
pub fn require_fluid(name: &str) -> &'static FluidInfo {
    let id = fluid(name).unwrap_or_else(|| panic!("unknown fluid `{name}`"));
    &FLUIDS[usize::from(id)]
}

/// The light source named `name` (`dwell:torch`; docs/LIGHTS.md).
pub fn light(name: &str) -> Option<&'static LightInfo> {
    LIGHTS.iter().find(|l| l.name == name)
}

/// FNV-1a 64 over the canonical strings (each followed by `\n`), in id order: what the generator
/// stores as [`REGISTRY_HASH`] and world files record.
pub fn compute_hash() -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for s in &STATES {
        for b in s.name.bytes().chain(std::iter::once(b'\n')) {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    h
}
